// 🎬 声色片场 · 动态加载器（卡版本 0.1.37）
// 本体在公开仓库 github.com/fannnnnnn5822/pianchang-card 的 dist/pianchang.js，走 jsDelivr。
// 先问 Supabase ac_config.pianchang_script_ref 要提交号（热更新不用重导卡），按 @提交号 拉；指针不通就拉 @v0.1.37（这张卡发版时的 tag）。
// pianchang_off 非空 = 作者临时关掉脚本，只弹那句话。
(function () {
  var REPO = 'fannnnnnn5822/pianchang-card', TAG = 'v0.1.37', CARD = '0.1.37';
  var POINTER_URL = 'https://hieylivlsdmyznviumht.supabase.co/rest/v1/ac_config?key=in.(pianchang_script_ref,pianchang_off)&select=key,value', POINTER_KEY = 'sb_publishable_MH80Xnlm1oHli6UXwzRpNA_EsC1DnCO';
  var L = function (m) { try { console.log('[声色片场 loader] ' + m); } catch (e) {} };
  function say(kind, msg) { try { toastr[kind](msg, '🎬 声色片场', { timeOut: 15000 }); } catch (e) {} L(msg); }
  if (/^__/.test(REPO) || /^__/.test(TAG)) { say('error', '加载器还没配地址（仓库 / tag 是占位）。用离线版脚本，或者等作者发版。'); return; }
  (async function () {
    var ref = '', off = '', code = null, how = '';
    if (POINTER_URL) {
      try {
        var c0 = (typeof AbortController !== 'undefined') ? new AbortController() : null, t0 = c0 ? setTimeout(function () { c0.abort(); }, 6000) : null;
        var r0 = await fetch(POINTER_URL, { cache: 'no-store', signal: c0 ? c0.signal : undefined, headers: POINTER_KEY ? { apikey: POINTER_KEY, Authorization: 'Bearer ' + POINTER_KEY } : {} });
        if (t0) clearTimeout(t0);
        if (r0.ok) (await r0.json() || []).forEach(function (row) {
          var v = String((row && row.value) || '').trim();
          if (row && row.key === 'pianchang_script_ref' && /^[A-Za-z0-9._-]{4,60}$/.test(v)) ref = v;
          if (row && row.key === 'pianchang_off' && v) off = v;
        });
        else L('指针 HTTP ' + r0.status);
      } catch (e0) { L('指针请求失败：' + ((e0 && e0.message) || e0)); }
    }
    if (off) { try { toastr.info(off, '🎬 声色片场', { timeOut: 0, extendedTimeOut: 0 }); } catch (e6) {} return; }
    var refs = ref ? [ref, TAG] : [TAG];
    var hosts = ['testingcf.jsdelivr.net', 'fastly.jsdelivr.net', 'cdn.jsdelivr.net'];
    for (var k = 0; k < refs.length && code == null; k++) {
      for (var i = 0; i < hosts.length && code == null; i++) {
        var url = 'https://' + hosts[i] + '/gh/' + REPO + '@' + refs[k] + '/dist/pianchang.js';
        try {
          var c1 = (typeof AbortController !== 'undefined') ? new AbortController() : null, t1 = c1 ? setTimeout(function () { c1.abort(); }, 12000) : null;
          var r1 = await fetch(url, { cache: 'no-store', signal: c1 ? c1.signal : undefined });
          if (t1) clearTimeout(t1);
          if (!r1.ok) throw new Error('HTTP ' + r1.status);
          var txt = await r1.text();
          if (!txt || txt.length < 50000 || txt.indexOf('PIANCHANG_CORE') < 0) throw new Error('内容不像片场脚本（' + (txt ? txt.length : 0) + ' 字）');
          code = txt; how = '@' + refs[k].slice(0, 9) + ' via ' + hosts[i];
        } catch (e1) { L('源 ' + hosts[i] + ' 失败：' + ((e1 && e1.message) || e1)); }
      }
    }
    if (code == null) { say('error', '片场脚本没连上网：要从 jsDelivr 下载，网络通了刷新一下就好。'); return; }
    L('卡 ' + CARD + '，用的是' + how + '（' + code.length + ' 字）');
    try { eval(code); } catch (e2) { say('error', '片场脚本启动出错：' + ((e2 && e2.message) || e2)); }
  })();
})();
